import json
from pathlib import Path

root = Path('.book-work/theexpanseuniverseontheedgeofchaos-v1-ab46a74b7303/translations/ro/full/chunks')
translations = {
    't000028': '''În The Expanse, politica nu este doar un fundal: ea este o forță care modelează destinul unor lumi întregi. Peisajul politic este un sistem multipolar complex, în care Pământul, Marte și Centura se află într-un joc permanent de alianțe, conflicte și rivalități pentru putere. Pământul, reprezentat de Organizația Națiunilor Unite, este un colos politic care se confruntă cu suprapopularea și penuria de resurse. Politicienii săi trebuie să pună în balanță nevoile miliardelor de cetățeni, dintre care mulți depind de un venit de bază pentru a supraviețui, cu cerințele menținerii dominației Pământului în sistemul solar. Manevrele politice ale unor personaje precum Chrisjen Avasarala arată natura complicată și adesea ambiguă moral a guvernării în acest viitor. Marte, concentrat pe obiectivul îndelungat al terraformării, oferă un alt model politic. Republica Congresională Marțiană este mai unită în privința scopului decât Pământul, dar această unitate se obține cu prețul libertăților individuale.''',
    't000029': '''Tensiunea dintre obiectivele colective și libertatea personală revine constant în politica marțiană. Centura, lipsită de un guvern unitar, este un focar de activism politic și elan revoluționar. Organizații precum Alianța Planetelor Exterioare (OPA) luptă pentru drepturile și independența celor din Centură, adesea prin mijloace violente. Parcursul politic al lui Fred Johnson, de la ofițer al armatei pământene la lider al OPA, ilustrează loialitățile complexe și alianțele schimbătoare din această regiune instabilă. Pe măsură ce povestea avansează, vedem cum reacționează aceste entități politice la provocări fără precedent, de la amenințarea protomoleculei la deschiderea porților inelare. The Expanse arată că, până și în fața unor evenimente care schimbă întreaga paradigmă, natura fundamentală a luptei pentru putere politică rămâne aceeași. Economia din The Expanse este o extrapolare fascinantă a tendințelor actuale la scara întregului sistem solar.''',
    't000030': '''Motorul fundamental al acestei economii îl reprezintă resursele: apa, aerul, mineralele și spațiul locuibil sunt adevăratele monede de schimb.''',
    't000031': '''În ciuda problemelor sale de mediu, Pământul rămâne o mare putere agricolă, producând hrană pentru o bună parte a sistemului solar. Marte, bogat în tehnologie și forță militară, nu se poate hrăni fără importuri. Centura și planetele exterioare, deși bogate în resurse minerale, depind de planetele interioare pentru necesități vitale precum apa și aerul. Această interdependență creează o rețea complicată de relații comerciale și tensiuni economice. Oamenii din Centură se simt îndeosebi exploatați: munca și resursele lor ajung pe planetele interioare, în timp ce ei se luptă pentru supraviețuire. Inegalitatea economică este o sursă majoră a tensiunilor politice care pun povestea în mișcare. Apariția unor tehnologii noi, precum propulsorul Epstein, care face posibile călătoriile spațiale pe distanțe mari, arată cum progresul științific poate remodela peisajul economic.''',
    't000032': '''Descoperirea porților inelare la marginea sistemului solar promite să răstoarne din nou ordinea economică, oferind acces la mii de lumi noi și la resurse de neimaginat. Prin toate aceste schimbări economice, The Expanse explorează penuria, distribuția și costul uman al progresului economic. Ne întreabă dacă, într-un viitor al abundenței, vom găsi modalități de a împărți resursele echitabil sau vom reproduce inegalitățile de astăzi la o scară mai mare. Țesătura socială din The Expanse este la fel de diversă și complexă ca mediile colonizate de oameni. Fiecare regiune a spațiului și-a dezvoltat propria cultură, modelată de istorie, mediu și relația cu celelalte părți ale sistemului solar. Pe Pământ vedem o societate care se confruntă cu inegalități uriașe.''',
    't000033': '''În timp ce unii trăiesc în lux, majoritatea depind de venitul de bază și se străduiesc să-și găsească un rost într-o lume în care locurile de muncă tradiționale sunt puține. Apar astfel întrebări despre natura muncii, a scopului și a valorii sociale într-o epocă a automatizării și abundenței. Societatea marțiană, în schimb, este foarte motivată și militarizată. De la fiecare marțian se așteaptă o contribuție la marele proiect al terraformării. Acest scop comun creează o identitate națională puternică, dar duce și la o anumită rigiditate și intoleranță față de disidență. Cultura celor din Centură este poate cea mai vie și mai diversă. Născută din amestecul culturilor pământene și modelată de condițiile aspre ale vieții în spațiu, societatea lor este adaptabilă, rezistentă și profund independentă. Fiziologia, limba și obiceiurile lor distincte îi deosebesc de ceilalți, ceea ce duce adesea la discriminare și conflicte cu planetele interioare.''',
    't000034': '''The Expanse nu evită aspectele întunecate ale acestor dinamici sociale: rasismul, exploatarea și tribalismul sunt teme recurente. Dar arată și posibilitatea înțelegerii și cooperării peste granițele culturale, adesea prin echipajul divers al navei Rocinante. Pe măsură ce seria avansează, vedem cum reacționează aceste societăți la schimbări fără precedent. Descoperirea unor lumi locuibile dincolo de porțile inelare declanșează un nou val de colonizare, transformând structurile sociale și punând sub semnul întrebării raporturile de putere consacrate. Prin toate acestea, The Expanse ne amintește că, oricât de departe am călători și oricât ne-am schimba, provocările fundamentale ale construirii unei societăți drepte și echitabile rămân.''',
    't000035': '''Capitolul 5 — Aventuri și descoperiri în The Expanse''',
    't000036': '''În centrul vastei narațiuni din The Expanse se află călătoria navei Rocinante și a echipajului său. Această fostă navă de război marțiană, preluată de James Holden și echipa sa diversă, devine un microcosmos al universului mai larg: un loc în care pământenii, marțienii și oamenii din Centură trebuie să învețe să lucreze împreună în fața unor șanse copleșitoare. Aventurile navei Rocinante ne poartă din centura de asteroizi către planetele exterioare și mai departe, fiecare misiune dezvăluind alte fațete ale acestui univers complex. Transformarea navei dintr-un vas de război furat într-un simbol al cooperării interplanetare oglindește temele mai ample ale seriei. Prin bătălii, anchete și prime contacte, echipajul navei Rocinante ne arată ce este mai bun și mai rău în umanitatea ajunsă în spațiu.''',
    't000037': '''Una dintre cele mai palpitante aventuri este cursa navei Rocinante prin poarta inelară, către un spațiu necunoscut. Momentul, încărcat de tensiune și uimire, concentrează spiritul de explorare care animă seria. Când nava trece prin poartă, ne ținem răsuflarea asemenea echipajului, fără să știm ce se află dincolo. Evenimentele de pe stația Eros constituie una dintre cele mai înfiorătoare și importante aventuri din The Expanse. Ceea ce începe ca o misiune obișnuită de securitate pentru detectivul Miller se transformă într-un coșmar când protomolecula este eliberată asupra populației stației. Groaza de pe Eros se desfășoară ca un experiment științific monstruos, protomolecula rescriind însăși natura biologiei umane. Cursa pentru a scăpa de pe stația condamnată, cu Miller și Holden străbătând coridoare pline de oameni transformați grotesc, este o lecție de horror cosmic.''',
    't000038': '''Această aventură oferă nu doar acțiune intensă, ci și introducerea protomoleculei ca element care schimbă regulile jocului. Urmările de pe Eros, când stația sfidează legile fizicii și pornește către Pământ, duc la una dintre cele mai tensionate secvențe ale seriei. Eforturile de a devia sau distruge Eros arată ingeniozitatea oamenilor în criză și natura de nepătruns a tehnologiei extraterestre pe care o înfruntă. Descoperirea porților inelare deschide mii de lumi noi pentru explorare, ducând la unele dintre cele mai fascinante aventuri ale seriei. Colonizarea planetei Ilus (sau New Terra) este un exemplu grăitor al provocărilor și minunilor întâlnite la așezarea pe planete extraterestre. Odată cu sosirea primei nave coloniale importante, asistăm la ciocnirea dintre coloniștii oportuniști din Centură și expediția oficială pământeană. Planeta însăși devine un personaj, iar ecologia sa extraterestră aduce amenințări neprevăzute.''',
    't000039': '''De la dezastre naturale care cuprind întreaga planetă la întâlniri cu tehnologii extraterestre străvechi, aventura de pe Ilus surprinde spiritul explorării și primejdiile colonizării unor lumi necunoscute. Această poveste explorează și latura antropologică a colonizării, arătând cum culturi umane diferite se adaptează unor medii noi și intră în conflict din cauza lor. Lupta dintre coloniști, interesele corporative și tehnologia extraterestră autohtonă oferă un cadru complex pentru examinarea colonialismului și a adaptării umane.''',
    't000040': '''Crearea Zonei Lente și deschiderea spațiului inelar reprezintă o schimbare de paradigmă în serie, extinzând exponențial posibilitățile explorării umane. Prima călătorie în spațiul inelar este plină de pericol și uimire în egală măsură. Incidentul din Zona Lentă, când navele sunt oprite brusc, iar echipajele lor sunt supuse unor forțe gravitaționale extreme, este una dintre cele mai tensionate secvențe ale seriei. El arată pericolele întâlnirii cu o tehnologie extraterestră de neînțeles și cât de repede trebuie să gândești pentru a supraviețui în spațiu. Explorarea spațiului inelar și a nodului care leagă mii de alte sisteme solare deschide posibilități nelimitate de aventură. Fiecare poartă nouă poate aduce o poveste, o lume de explorat și noi pericole. Această extindere a universului îi permite seriei The Expanse să abordeze expansiunea umană, etica colonizării și posibilitatea întâlnirii cu alte forme de viață inteligentă.''',
    't000041': '''Apariția Laconiei aduce una dintre cele mai interesante și tulburătoare aventuri din ultima parte a seriei. O forță militară desprinsă de celelalte, care folosește tehnologia extraterestră găsită dincolo de inele, revine în sistemul solar ca un imperiu redutabil. Confruntarea cu Laconia împinge la limită tehnologia și înțelegerea umană. Ea introduce concepte precum „câinii stranii”, entități extraterestre capabile de înviere, și nave care se pot repara singure, aducând provocări fără precedent pentru omenire. Această aventură obligă personajele și cititorii să se confrunte cu întrebări despre evoluția umană și prețul folosirii unei tehnologii extraterestre pe care nu o înțelegem pe deplin. Povestea Laconiei oferă și unele dintre cele mai ample bătălii spațiale ale seriei, când noul imperiu se ciocnește de forțele reunite ale Pământului, lui Marte și Centurii. Aceste conflicte arată fidelitatea seriei față de un război spațial realist, chiar dacă îi lărgesc limitele prin tehnologie avansată.''',
    't000042': '''Seria culminează cu poate cea mai mare aventură a sa: o călătorie în necunoscutul care depășește înțelegerea umană. Pe măsură ce se dezvăluie adevărata natură și intențiile constructorilor inelelor și ale celor care i-au distrus, omenirea se confruntă cu întrebări existențiale despre locul ei în univers.''',
    't000043': '''Această aventură finală depășește opera spațială tradițională și pătrunde în domeniul speculației metafizice și al uimirii cosmice. Echipajul navei Rocinante, alături de figuri importante din întregul spațiu locuit de oameni, trebuie să înfrunte entități și concepte care le răstoarnă înțelegerea realității. Călătoria reunește fire narative răspândite de-a lungul seriei: protomolecula, constructorii inelelor, agresorii necunoscuți care i-au distrus. Rezultatul este o țesătură cosmică în același timp grandioasă și înspăimântătoare. Ea ridică întrebări despre natura conștiinței, caracterul ciclic al civilizațiilor și rolul omenirii într-un univers cu mult mai vast și mai straniu decât ne-am imaginat vreodată. În toate aceste aventuri, The Expanse revine neîncetat la dimensiunea umană. Fie că înfruntă amenințări extraterestre, traversează câmpuri minate politice sau împing limitele spațiului cunoscut, poveștile oamenilor sunt cele care ne mișcă cel mai profund.''',
    't000044': '''Vedem personaje care se luptă cu propriile limite și prejudecăți, încheagă alianțe neașteptate și descoperă o forță pe care nu știau că o au. Echipajul divers al navei Rocinante — idealismul lui Holden, strălucirea tehnică a lui Naomi, pragmatismul dur al lui Amos și calmul lui Alex — arată fațete diferite ale umanității, fiecare esențială pentru supraviețuirea în întinderea neiertătoare a spațiului. Aceste călătorii și descoperiri nu sunt doar aventuri captivante, ci și oglinzi ale societății noastre. Ne îndeamnă să ne gândim cum am reacționa în fața necunoscutului, cum s-ar adapta structurile noastre sociale la noi frontiere și ce trăsături ale umanității trebuie să păstrăm chiar și atunci când evoluăm și ne răspândim printre stele.''',
    't000045': '''Concluzie''',
    't000046': '''În concluzie, „The Expanse” excelează în prezentarea unei viziuni complexe și captivante asupra posibilei evoluții a omenirii într-un univers vast. Rămânând fidelă trăsăturilor fundamentale ale naturii umane, seria ne obligă să privim în față o mulțime de provocări noi și imprevizibile. Fiecare personaj, planetă și conflict ilustrează un adevăr esențial: oricât de departe ne-am aventura în cosmos, vechile lupte pentru resurse, putere și identitate continuă să ne definească existența. Seria înfățișează cu măiestrie complexitatea politicii interplanetare, în care alianțele se schimbă și trădările pândesc, amintindu-ne că aceste dinamici rămân la fel de relevante la scară uriașă ca în viața de zi cu zi. Această rețea complicată de relații devine un microcosmos al societății umane și reflectă dorința noastră neîntreruptă de a gestiona conflictele și de a căuta cooperarea, chiar și în împrejurările cele mai grele.''',
    't000047': '''Mai mult, „The Expanse” subliniază capacitatea noastră înnăscută de adaptare și inovare. Pune întrebări esențiale despre natura progresului: ce înseamnă să evoluăm ca specie? Călătoriile personajelor arată că supraviețuirea nu ține doar de rezistență, ci și de schimbarea valorilor noastre și a felului în care ne raportăm unii la alții și la mediu. Prin încercările lor, vedem importanța colaborării și empatiei, care arată că adevăratul progres depinde de capacitatea noastră de a ne uni în jurul unui scop comun. Pe măsură ce pătrundem în narațiunea sa bogată, seria îi invită pe spectatori să reflecteze la propriile vieți și la direcția mai largă a omenirii. Ne amintește cu forță că alegerile de astăzi vor avea ecou în viitor, modelând nu doar societățile noastre, ci și locul nostru în univers.''',
    't000048': '''Provocându-ne să ne imaginăm cum putem păstra ce este mai bun în umanitatea noastră și, în același timp, să renunțăm la tiparele dăunătoare ale trecutului, „The Expanse” face mai mult decât să ofere divertisment: inspiră reflecție critică asupra călătoriei noastre comune. Astfel, ne îndeamnă să ne folosim potențialul pentru a crea un viitor care să nu fie doar o prelungire a istoriei, ci un nou capitol îndrăzneț al omenirii printre stele.''',
    't000049': '''Bibliografie''',
    't000050': '''„The Expanse: A Companion”, de James S. A. Corey''',
    't000051': '''„The Expanse: A History of the Future”, de James S. A. Corey''',
}

for number in range(5, 9):
    path = root / f'{number:04}.json'
    chunk = json.loads(path.read_text())
    for segment in chunk['segments']:
        if segment['id'] in translations:
            segment['translation'] = translations[segment['id']]
    path.write_text(json.dumps(chunk, ensure_ascii=False, indent=2) + '\n')
print(f'Saved {len(translations)} translated segments')
